<div class="wrap"><a href="<?= url('/help/tickets') ?>" class="small"><i class="bi bi-arrow-left"></i> Tickets</a>
  <h1 class="page-title mt-1">#<?= (int)$t['id'] ?> · <?= e($t['subject']) ?></h1><span class="tag <?= $t['status'] === 'closed' ? 'gray' : 'green' ?>"><?= e($t['status']) ?></span>
